Demande : « Les clients inscrits en octobre 2026. »
SELECT * FROM clients
WHERE date_inscription BETWEEN '2026-10-01' AND '2026-10-30';

Petición: «Productos sin stock que sigan publicados en la tienda.»
SELECT sku, nombre FROM productos
WHERE stock = 0 AND publicado = TRUE;

Petición: «Empleados del departamento de Ventas con más de 5 años de antigüedad.»
SELECT nombre FROM empleados
WHERE departamento = 'Ventas' AND antiguedad_anios >= 5;
